import 'package:flutter/material.dart';
void main()=>runApp(const App());
class App extends StatelessWidget{const App({super.key});@override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,home:const Tela());}
class Tela extends StatefulWidget{const Tela({super.key});@override State<Tela> createState()=>_TelaState();}
class _TelaState extends State<Tela>{final produto=TextEditingController(),preco=TextEditingController(),quantidade=TextEditingController();String resultado='';void calcular(){final p=double.tryParse(preco.text.replaceAll(',','.')),q=int.tryParse(quantidade.text);if(produto.text.trim().isEmpty||p==null||q==null||q<0){setState(()=>resultado='Preencha os campos corretamente.');return;}final subtotal=p*q,desconto=subtotal>500?subtotal*.1:0;setState(()=>resultado='Produto: ${produto.text}\nQuantidade: $q\nSubtotal: R\$ ${subtotal.toStringAsFixed(2)}\nDesconto: R\$ ${desconto.toStringAsFixed(2)}\nTotal: R\$ ${(subtotal-desconto).toStringAsFixed(2)}');}void limpar(){produto.clear();preco.clear();quantidade.clear();setState(()=>resultado='');}@override void dispose(){produto.dispose();preco.dispose();quantidade.dispose();super.dispose();}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Sistema de vendas')),body:Padding(padding:const EdgeInsets.all(16),child:Column(children:[TextField(controller:produto,decoration:const InputDecoration(labelText:'Produto')),TextField(controller:preco,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Preço unitário')),TextField(controller:quantidade,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Quantidade')),const SizedBox(height:20),Row(mainAxisAlignment:MainAxisAlignment.center,children:[ElevatedButton(onPressed:calcular,child:const Text('Calcular')),const SizedBox(width:12),ElevatedButton(onPressed:limpar,child:const Text('Limpar'))]),const SizedBox(height:24),Text(resultado)])));}
